<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Closure; use Throwable; use Pterodactyl\Models\Server; use Illuminate\Support\Facades\Log; use Illuminate\Support\Facades\Cache; class ModpackBootstrap { private const INSTALL_SCRIPTS = ['FTBInstall.sh', 'Install.sh', 'install.sh', 'setup.sh']; private const START_SCRIPTS = [ 'run.sh', 'start.sh', 'startserver.sh', 'ServerStart.sh', 'LaunchServer.sh', 'start-server.sh', ]; private const INSTALLER_JAR = '/^(neo)?forge-.*installer.*\.jar$/i'; private const LEFTOVERS = ['installer.log', 'forge-installer.log']; private const POLL_SECONDS = 5; private const BOOT_GRACE = 30; private const STOP_SECONDS = 60; private const MAX_PASSES = 2; private const HELD_TTL = 21_600; private const ROOT_MARKERS = [ 'libraries', 'config', 'defaultconfigs', 'mods', 'plugins', 'world', 'server.properties', 'eula.txt', ]; public function __construct(private readonly LaunchConfigurator $configurator) { } public function handle( Server $server, ServerFiles $files, string $minecraft = '', Closure|null $progress = null, ): array { $say = $progress ?? fn (string $message) => null; self::restore($server); $this->unwrap($files, $say); $ran = null; for ($pass = 0; $pass < self::MAX_PASSES; ++$pass) { if ($this->configurator->argfile($files) !== null) { break; } $step = $this->install($server, $files, $say); if ($step === null) { break; } $ran = $step; } $say('Setting the startup command.'); $result = $this->configurator->apply( $server, $files, VersionCatalog::javaForVersion($minecraft), ); if ($result['target'] === null) { $script = $this->startScript($files); if ($script !== null && $this->useScript($server, $files, $script)) { $result['target'] = './' . $script; $result['mode'] = 'script'; } } return $result + ['ran' => $ran]; } private function install(Server $server, ServerFiles $files, Closure $say): ?string { $root = $files->listFiles('/') ?? []; $jar = $this->match($root, fn (string $name) => preg_match(self::INSTALLER_JAR, $name) === 1); if ($jar !== null) { $say("Running {$jar}. This takes a few minutes."); $this->run( $server, $files, 'java -jar ' . escapeshellarg($jar) . ' --installServer', 30, ); $files->deletePaths('/', [$jar]); foreach (self::LEFTOVERS as $leftover) { $files->deletePaths('/', [$leftover]); } return $jar; } $binary = $this->match($root, fn (string $name) => str_starts_with($name, 'serverinstall_') || str_starts_with($name, 'ftb-server-installer')); if ($binary !== null) { $say("Running {$binary}. This downloads the whole pack and takes a few minutes."); $files->chmod('/', $binary, '0755'); $this->run( $server, $files, './' . escapeshellarg($binary) . ' --auto --nojava', 45, ); $files->deletePaths('/', [$binary]); return $binary; } $script = $this->match($root, fn (string $name) => in_array($name, self::INSTALL_SCRIPTS, true)); if ($script !== null) { $say("Running {$script}."); $files->chmod('/', $script, '0755'); $this->run($server, $files, './' . escapeshellarg($script), 30); return $script; } return null; } private function useScript(Server $server, ServerFiles $files, string $script): bool { $files->chmod('/', $script, '0755'); try { $server->forceFill(['startup' => './' . $script])->saveOrFail(); } catch (Throwable $exception) { Log::warning('Could not point a server at its modpack start script', [ 'server' => $server->uuid, 'script' => $script, 'error' => $exception->getMessage(), ]); return false; } return true; } private function startScript(ServerFiles $files): ?string { $root = $files->listFiles('/') ?? []; foreach (self::START_SCRIPTS as $candidate) { $found = $this->match($root, fn (string $name) => $name === $candidate); if ($found !== null) { return $found; } } return null; /* 9ccf7ef3d192b3433f7b8d474083ece9 */ } private function unwrap(ServerFiles $files, Closure $say): void { $root = array_values(array_filter( $files->listFiles('/') ?? [], fn (array $entry) => !str_starts_with((string) ($entry['name'] ?? ''), '.'), )); if (count($root) !== 1 || !($root[0]['directory'] ?? false)) { return; } $folder = (string) $root[0]['name']; $inside = $files->listFiles('/' . $folder) ?? []; if ($inside === [] || !$this->looksLikeRoot($inside)) { return; } $say("Moving the pack out of {$folder}."); foreach ($inside as $entry) { $name = (string) ($entry['name'] ?? ''); if ($name !== '') { $files->renamePath('/', $folder . '/' . $name, $name); } } $files->deletePaths('/', [$folder]); } private function looksLikeRoot(array $entries): bool { foreach ($entries as $entry) { $name = mb_strtolower((string) ($entry['name'] ?? '')); if (in_array($name, self::ROOT_MARKERS, true)) { return true; } if (!($entry['directory'] ?? false) && str_ends_with($name, '.sh')) { return true; } } return false; } private function match(array $entries, Closure $matches): ?string { foreach ($entries as $entry) { $name = (string) ($entry['name'] ?? ''); if ($name !== '' && !($entry['directory'] ?? false) && $matches($name)) { return $name; } } return null; } private function run(Server $server, ServerFiles $files, string $command, int $minutes): bool { $original = (string) $server->startup; if (!$this->stop($files)) { return false; } Cache::put(self::heldKey($server), $original, self::HELD_TTL); try { $server->forceFill(['startup' => $command])->saveOrFail(); } catch (Throwable $exception) { Cache::forget(self::heldKey($server)); Log::warning('Could not set an installer startup command', [ 'server' => $server->uuid, 'error' => $exception->getMessage(), ]); return false; } $finished = false; try { $files->setPower('start'); $finished = $this->awaitExit($files, $minutes); if (!$finished) { Log::warning('A modpack installer did not finish in time', [ 'server' => $server->uuid, 'command' => $command, ]); $files->setPower('kill'); } } finally { try { $server->forceFill(['startup' => $original])->saveOrFail(); Cache::forget(self::heldKey($server)); } catch (Throwable $exception) { Log::error('Could not restore a startup command after an install', [ 'server' => $server->uuid, 'startup' => $original, 'error' => $exception->getMessage(), ]); } } return $finished; } public static function restore(Server $server): void { $held = Cache::pull(self::heldKey($server)); if (!is_string($held) || $held === '' || $held === (string) $server->startup) { return; } Log::warning('Putting back a startup command an install left swapped out', [ 'server' => $server->uuid, 'stuck' => $server->startup, ]); try { $server->forceFill(['startup' => $held])->saveOrFail(); } catch (Throwable $exception) { Log::error('Could not put back a swapped-out startup command', [ 'server' => $server->uuid, 'error' => $exception->getMessage(), ]); } } private static function heldKey(Server $server): string { return 'modpack-startup:' . $server->uuid; } private function awaitExit(ServerFiles $files, int $minutes): bool { $deadline = microtime(true) + ($minutes * 60); $started = false; $offline = 0; while (microtime(true) < $deadline) { sleep(self::POLL_SECONDS); if ($files->powerState() !== 'offline') { $started = true; $offline = 0; continue; } $offline += self::POLL_SECONDS; if ($started || $offline >= self::BOOT_GRACE) { return true; } } return false; } private function stop(ServerFiles $files): bool { if ($files->powerState() === 'offline') { return true; } $files->setPower('kill'); $deadline = microtime(true) + self::STOP_SECONDS; do { sleep(3); if ($files->powerState() === 'offline') { return true; } } while (microtime(true) < $deadline); return false; } } 